/**
 * Session keys for handoff — the only secret material exported by this crate.
 *
 * `Debug` redacts key bytes; do not log the fields themselves.
 */
public struct SessionKeys {
    /**
     * 16-byte STS key for a ranging stack (e.g. UWB provisioned STS).
     */
    public var stsKey: Data
    /**
     * 32-byte transport key for a media / app stack.
     */
    public var transportKey: Data

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(
        /**
         * 16-byte STS key for a ranging stack (e.g. UWB provisioned STS).
         */stsKey: Data, 
        /**
         * 32-byte transport key for a media / app stack.
         */transportKey: Data) {
        self.stsKey = stsKey
        self.transportKey = transportKey
    }
}



extension SessionKeys: Equatable, Hashable {
    public static func ==(lhs: SessionKeys, rhs: SessionKeys) -> Bool {
        if lhs.stsKey != rhs.stsKey {
            return false
        }
        if lhs.transportKey != rhs.transportKey {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(stsKey)
        hasher.combine(transportKey)
    }
}


