// See https://github.com/mozilla/uniffi-rs/issues/396 for further discussion.
/**
 * Sans-I/O pairing step for the host to handle.
 */

public enum PairingEvent {
    
    case awaitingMessage
    case sendMessage(data: Data
    )
    /**
     * Six decimal digits as a string (e.g. `"483984"`). Confirm out-of-band.
     */
    case confirmSas(digits: String
    )
    /**
     * Peer was stored in the engine; only the opaque id is returned.
     */
    case complete(peerId: PeerId
    )
    case failed(message: String
    )
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypePairingEvent: FfiConverterRustBuffer {
    typealias SwiftType = PairingEvent

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> PairingEvent {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .awaitingMessage
        
        case 2: return .sendMessage(data: try FfiConverterData.read(from: &buf)
        )
        
        case 3: return .confirmSas(digits: try FfiConverterString.read(from: &buf)
        )
        
        case 4: return .complete(peerId: try FfiConverterTypePeerId.read(from: &buf)
        )
        
        case 5: return .failed(message: try FfiConverterString.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: PairingEvent, into buf: inout [UInt8]) {
        switch value {
        
        
        case .awaitingMessage:
            writeInt(&buf, Int32(1))
        
        
        case let .sendMessage(data):
            writeInt(&buf, Int32(2))
            FfiConverterData.write(data, into: &buf)
            
        
        case let .confirmSas(digits):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(digits, into: &buf)
            
        
        case let .complete(peerId):
            writeInt(&buf, Int32(4))
            FfiConverterTypePeerId.write(peerId, into: &buf)
            
        
        case let .failed(message):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(message, into: &buf)
            
        }
    }
}


